  "блузу": "Значење: Падежни облик речи блуза; горњи део одеће.\n\nГраматика: Именица; инструментал.",
  "бобом": "Значење: Падежни облик речи боб; зрнастом биљком или зрном.\n\nГраматика: Именица; инструментал.",
  "богаљ": "Значење: Особа са тешким телесним недостатком; реч може бити груба.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "богат": "Значење: Онај који има много имовине, садржаја или вредности.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "богме": "Значење: Узречица којом се нешто потврђује или наглашава.\n\nГраматика: Именица; номинатив; множина.",
  "богом": "Значење: Бог.\n\nГраматика: Именица; инструментал.",
  "бодеж": "Значење: Кратко хладно оружје са оштрицом.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "бодље": "Значење: Оштри шиљци на биљци, животињи или предмету.\n\nГраматика: Именица; номинатив; множина.",
  "божић": "Значење: Хришћански празник рођења Христовог.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "божја": "Значење: Женски облик придева божји; оно што припада Богу или је од Бога.\n\nГраматика: Именица; генитив; једнина.",
  "божје": "Значење: Средњи род или множина придева божји.\n\nГраматика: Именица; номинатив; множина.",
  "божји": "Значење: Онај који припада Богу или је у вези са Богом.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "божју": "Значење: Падежни облик придева божји.\n\nГраматика: Именица; акузатив.",
  "бојао": "Значење: Наносио боју или се плашио.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
  "бојде": "Значење: Разговорни или регионални облик; у бази се третира као посебна реч.\n\nГраматика: Именица; номинатив; множина.",
  "бојим": "Значење: Радити или се нечим занимати.\n\nГраматика: Глагол; презент; 1. лице; једнина.",
  "бојиш": "Значење: Давати боју или осећати страх.\n\nГраматика: Глагол; презент; 2. лице; једнина.",
  "бојни": "Значење: Онај који се односи на бој, војску или борбу.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "бојно": "Значење: Средњи род речи бојни.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "бојом": "Значење: Боја; боја, нијанса.\n\nГраматика: Именица; инструментал.",
  "бојте": "Значење: Ви бојте нешто.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "бокал": "Значење: Посуда са дршком за воду, вино или друго пиће.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "бокса": "Значење: Облик речи бокс; спорт у ком се противници боре песницама.\n\nГраматика: Именица; генитив; једнина.",
  "бокца": "Значење: Облик речи бок или бокца; може означавати страну или малу преграду.\n\nГраматика: Именица; генитив; једнина.",
  "болан": "Значење: Онај који осећа бол или изазива бол.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "болна": "Значење: Облик од „речи болан”.\n\nГраматика: Именица; генитив; једнина.",
  "болне": "Значење: Множина или падежни облик речи болан.\n\nГраматика: Именица; номинатив; множина.",
  "болни": "Значење: Који боли или изазива бол.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "болно": "Значење: На начин који изазива или прати бол.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "болом": "Значење: Падежни облик речи бол; осећајем патње или повреде.\n\nГраматика: Именица; инструментал.",
