  "бољом": "Значење: Падежни облик придева бољи.\n\nГраматика: Именица; инструментал.",
  "бомба": "Значење: Експлозивна направа; у говору и нешто снажно или упечатљиво.\n\nГраматика: Именица; генитив; једнина.",
  "бомбе": "Значење: Множина или падежни облик речи бомба.\n\nГраматика: Именица; номинатив; множина.",
  "бомби": "Значење: Падежни облик речи бомба.\n\nГраматика: Придев; мушки род; номинатив; множина.",
  "бомбу": "Значење: Падежни облик речи бомба; експлозивну направу.\n\nГраматика: Именица; акузатив.",
  "бонго": "Значење: Мали ручни бубањ, најчешће у пару.\n\nГраматика: Прилог.",
  "бонус": "Значење: Додатак, награда или нешто што се добија преко основног.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "борац": "Значење: Онај који се бори; ратник, такмичар или упорна особа.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "борба": "Значење: Сукоб, надметање или упоран напор да се нешто постигне.\n\nГраматика: Именица; генитив; једнина.",
  "борбе": "Значење: Множина или падежни облик речи борба.\n\nГраматика: Именица; номинатив; множина.",
  "борби": "Значење: Падежни облик речи борба; сукобу или настојању.\n\nГраматика: Придев; мушки род; номинатив; множина.",
  "борбу": "Значење: Падежни облик речи борба.\n\nГраматика: Именица; акузатив.",
  "бордо": "Значење: Тамноцрвена боја; може означавати и град Бордо.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "борим": "Значење: Борим се; супротстављам се или напрежем.\n\nГраматика: Глагол; презент; 1. лице; једнина.",
