  "бориш": "Значење: Бориш се; супротстављаш се или напрежеш.\n\nГраматика: Глагол; презент; 2. лице; једнина.",
  "борца": "Значење: Онај који се бори; ратник, такмичар или упорна особа.\n\nГраматика: Именица; генитив; једнина.",
  "борце": "Значење: Множина или падежни облик речи борац.\n\nГраматика: Именица; номинатив; множина.",
