  "боцом": "Значење: Падежни облик речи боца; флашом или посудом.\n\nГраматика: Именица; инструментал.",
  "бочне": "Значење: Множина или падежни облик речи бочни; оно што је са стране.\n\nГраматика: Именица; номинатив; множина.",
  "бочни": "Значење: Онај који је са стране или се односи на бок.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
