  "браде": "Значење: Множина или падежни облик речи брада.\n\nГраматика: Именица; номинатив; множина.",
  "бради": "Значење: Падежни облик речи брада; длакама на доњем делу лица.\n\nГраматика: Придев; мушки род; номинатив; множина.",
