  "брака": "Значење: Падежни облик речи брак; заједнице супружника.\n\nГраматика: Именица; генитив; једнина.",
  "браку": "Значење: Брак.\n\nГраматика: Именица; акузатив.",
  "брале": "Значење: Разговорни облик обраћања, слично речи брате.\n\nГраматика: Именица; номинатив; множина.",
  "брана": "Значење: Грађевина која зауставља или усмерава воду.\n\nГраматика: Именица; генитив; једнина.",
