  "брани": "Значење: Штити или не дозвољава напад.\n\nГраматика: Глагол; презент; 3. лице; једнина.",
  "брану": "Значење: Падежни облик речи брана.\n\nГраматика: Именица; датив.",
  "бранч": "Значење: Касни доручак који спаја доручак и ручак.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "браон": "Значење: Смеђа боја.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "брата": "Значење: Брат; мушки рођак истог родитеља.\n\nГраматика: Именица; генитив; једнина.",
