  "метал": "Значење: Чврст материјал као гвожђе, бакар или злато.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "метан": "Значење: Запаљив гас без боје и мириса.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "метар": "Значење: Основна мера за дужину.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "метеж": "Значење: Гужва, неред или пометња.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "метка": "Значење: Облик речи метак; пројектила или муниције.\n\nГраматика: Именица; генитив; једнина.",
