  "метла": "Значење: Алат за чишћење пода.\n\nГраматика: Именица; генитив; једнина.",
  "метле": "Значење: Множина или облик речи метла.\n\nГраматика: Именица; номинатив; множина.",
  "метлу": "Значење: Метла; алат за чишћење пода.\n\nГраматика: Именица; датив.",
  "метод": "Значење: Начин рада, поступак или систем за постизање циља.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "метом": "Значење: Облик речи мета; циљем у који се гађа или коме се тежи.\n\nГраматика: Именица; инструментал.",
  "метра": "Значење: Облик речи метар; јединица мере за дужину.\n\nГраматика: Именица; генитив; једнина.",
  "метро": "Значење: Градска подземна или брза железница.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "мехур": "Значење: Балончић ваздуха или течности; и орган који задржава течност.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
