  "мешај": "Значење: Заповедни облик глагола мешати; померај састојке да се споје.\n\nГраматика: Глагол; заповедни мод (императив).",
  "мешам": "Значење: Мешати.\n\nГраматика: Глагол; презент; 1. лице; једнина.",
  "мешао": "Значење: Он је мешао.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
