  "минус": "Значење: Знак за одузимање; негативна вредност или недостатак.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "минут": "Значење: Јединица времена од шездесет секунди.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "мираз": "Значење: Имовина коју невеста доноси у брак.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "миран": "Значење: Тих, спокојан или без узбуђења.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "мирис": "Значење: Осећај који примамо чулом мириса; пријатан или непријатан задах.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "мирна": "Значење: Женски облик речи миран; тиха и спокојна.\n\nГраматика: Именица; генитив; једнина.",
  "мирне": "Значење: Облик речи миран; оне које су тихе или спокојне.\n\nГраматика: Именица; номинатив; множина.",
  "мирни": "Значење: Који су тихи, спокојни или без немира.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "мирно": "Значење: На миран начин; тихо и без узбуђења.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "мирну": "Значење: Облик речи миран; ону која је тиха или спокојна.\n\nГраматика: Именица; датив.",
  "миром": "Значење: Облик речи мир; спокојем или стањем без сукоба.\n\nГраматика: Именица; инструментал.",
  "мируј": "Значење: Заповедни облик глагола мировати; остани миран.\n\nГраматика: Глагол; заповедни мод (императив).",
  "мисао": "Значење: Оно што се мисли; идеја или размишљање.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "мисле": "Значење: Мислити.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "мисли": "Значење: Радња везана за „мисли”.\n\nГраматика: Глагол; презент; 3. лице; једнина.",
  "мичем": "Значење: Мицати.\n\nГраматика: Глагол; презент; 1. лице; једнина.",
  "мишић": "Значење: Ткиво које покреће тело; и мали миш у говору.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "мишљу": "Значење: Облик речи мисао; идејом или размишљањем.\n\nГраматика: Именица; датив.",
  "млада": "Значење: Женски облик речи млад; може значити и жена на венчању.\n\nГраматика: Именица; генитив; једнина.",
  "младе": "Значење: Множина или падежни облик речи млад.\n\nГраматика: Именица; номинатив; множина.",
  "млади": "Значење: Они који су млади; или облик речи млад.\n\nГраматика: Придев; мушки род; номинатив; множина.",
  "младо": "Значење: Средњи род речи млад; оно што је младо.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "младу": "Значење: Облик речи млад или млада; младу особу или невесту.\n\nГраматика: Именица; акузатив.",
  "млађа": "Значење: Женски облик речи млађи; она која има мање година.\n\nГраматика: Именица; генитив; једнина.",
  "млађе": "Значење: Средњи род или множина речи млађи.\n\nГраматика: Именица; номинатив; множина.",
  "млађи": "Значење: Компаратив речи млад; онај који има мање година.\n\nГраматика: Придев; мушки род; номинатив; множина.",
  "млађу": "Значење: Облик речи млађи; ону која је млађа.\n\nГраматика: Именица; акузатив.",
  "млако": "Значење: Ни топло ни хладно; умерене, слабе топлоте.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
