  "обићи": "Значење: Заобићи, посетити или проћи око нечега.\n\nГраматика: Именица; номинатив; множина.",
  "облак": "Значење: Скуп ситних капљица воде или леда у атмосфери.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "облик": "Значење: Спољашњи изглед, форма или начин уређења нечега.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
