  "обред": "Значење: Свечани, верски или устаљени поступак.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "обриј": "Значење: Заповедни облик глагола обријати; скини длаке бријачем.\n\nГраматика: Глагол; заповедни мод (императив).",
  "оброк": "Значење: Јело у одређено време дана.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
