  "оглед": "Значење: Проба, експеримент или покушај којим се нешто испитује.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "одаја": "Значење: Соба или просторија, често у кући или двору.\n\nГраматика: Именица; генитив; једнина.",
