  "одани": "Значење: Који су верни, привржени или посвећени.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "одати": "Значење: Открити тајну, показати нешто или указати почаст.\n\nГраматика: Глагол; инфинитив.",
