  "одбор": "Значење: Група људи изабрана да управља или одлучује о нечему.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "одвео": "Значење: Он је одвео.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
