  "поход": "Значење: Организован одлазак, војни или свечани пут.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "почев": "Значење: Почевши од; од неког тренутка или места.\n\nГраматика: Именица; номинатив; једнина.",
  "почео": "Значење: Почети; започети.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
  "почет": "Значење: Започет; онај који је почео.\n\nГраматика: Именица; номинатив; једнина.",
