  "почни": "Значење: Заповедни облик глагола почети; започни.\n\nГраматика: Глагол; заповедни мод (императив).",
  "почну": "Значење: Почети; започети.\n\nГраматика: Глагол; облик.",
  "пошао": "Значење: Поћи.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
