  "прате": "Значење: Они иду уз некога или посматрају.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "прати": "Значење: Прати; иде уз некога или чисти водом, зависно од нагласка.\n\nГраматика: Глагол; инфинитив.",
  "праха": "Значење: Облик речи прах; ситне суве материје.\n\nГраматика: Именица; генитив; једнина.",
