  "првој": "Значење: Облик редног броја први; оној која је прва.\n\nГраматика: Именица; датив; локатив.",
  "првом": "Значење: Облик редног броја први; оном који је први.\n\nГраматика: Именица; инструментал.",
  "пргав": "Значење: Нагле нарави, лако се љути.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "преда": "Значење: Он или она уручи или препусти.\n\nГраматика: Глагол; облик.",
  "преде": "Значење: Мачка може да преде.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "преди": "Значење: Прави нит.\n\nГраматика: Глагол; презент; 3. лице; једнина.",
