function fridayBonusTotal(data = loadFridayBonus()) {
  const competitiveBonus = Object.values(data.competitive || {}).reduce((sum, value) => sum + (Number(value) || 0), 0);
  return (Number(data.normalBonus) || 0) + competitiveBonus;
}

