function msUntilTomorrow() {
  const now = new Date();
  const tomorrow = new Date(now);
  tomorrow.setHours(24, 0, 0, 0);
  return Math.max(0, tomorrow - now);
}

function countdownText() {
  const totalSeconds = Math.ceil(msUntilTomorrow() / 1000);
  const hours = String(Math.floor(totalSeconds / 3600)).padStart(2, "0");
  const minutes = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0");
  const seconds = String(totalSeconds % 60).padStart(2, "0");
  return `${hours}:${minutes}:${seconds}`;
}

function updateCompetitiveCountdown() {
  const button = typeButtons.find((item) => item.dataset.type === "competitive");
  if (!button) return;
  const locked = Boolean(todayLock());
  button.classList.toggle("daily-locked", locked);
  button.disabled = false;
  if (locked) {
    button.dataset.countdown = countdownText();
    return;
  }
  delete button.dataset.countdown;
}

function supabaseConfigured() {
  return Boolean(
    SUPABASE_CONFIG.url &&
    SUPABASE_CONFIG.anonKey &&
    SUPABASE_CONFIG.anonKey !== "PASTE_SB_PUBLISHABLE_KEY_HERE"
  );
}

function supabaseUrl(path) {
  const base = SUPABASE_CONFIG.url.replace(/\/$/, "");
  const prefix = (SUPABASE_CONFIG.restPrefix ?? "/rest/v1").replace(/\/$/, "");
  return prefix ? `${base}${prefix}/${path}` : `${base}/${path}`;
}

function supabaseHeaders(extra = {}) {
  const headers = { ...extra };
  const key = SUPABASE_CONFIG.anonKey;
  if (key) {
    headers.apikey = key;
    headers.Authorization = `Bearer ${key}`;
  }
  if (/ngrok-free\.(app|dev)/i.test(SUPABASE_CONFIG.url || "")) {
    headers["ngrok-skip-browser-warning"] = "true";
  }
  return headers;
}

function supabaseJsonHeaders(extra = {}) {
  return supabaseHeaders({ "Content-Type": "application/json", ...extra });
}

