function renderListing() {
  const results = loadResults();
  const finalResults = results.filter(isFinalResult);
  listingListEl.innerHTML = "";
  if (playerNameInput) playerNameInput.value = loadPlayerName();
  if (playerStatsEl) {
    playerStatsEl.textContent = supabaseConfigured()
      ? "Унеси надимак за online статистику."
      : "Online статистика није активна док се не унесе Supabase key.";
  }
  listingMetaEl.textContent = supabaseConfigured()
    ? "онлајн..."
    : finalResults.length ? "локално" : "нема резултата";

  if (!finalResults.length) {
    const item = document.createElement("li");
    item.textContent = "Коначан такмичарски скор ће се појавити овде.";
    listingListEl.append(item);
    refreshOnlineLeaderboard();
    return;
  }

  finalResults.slice(0, 6).forEach((result) => {
    const item = document.createElement("li");
    const status = result.status === "finished" ? "готово" : "крај";
    const difference = scoreDifferenceValue(result.score, result.started || 0);
    item.textContent = `${result.date} · ${formatScore(difference)} · ${formatScore(result.started || 0)}/${formatScore(result.score || 0)} · ${result.completed}/4 · ${status}`;
    listingListEl.append(item);
  });
  refreshOnlineLeaderboard();
}

function renderOnlineLeaderboard(rows) {
  listingListEl.innerHTML = "";
  listingMetaEl.textContent = "СЕЗОНА TOP 100";
  const leaderboard = aggregateLeaderboard(rows);
  if (!leaderboard.length) {
    const item = document.createElement("li");
    item.textContent = "Још нема online резултата.";
    listingListEl.append(item);
    return;
  }

  leaderboard.forEach((row, index) => {
    const item = document.createElement("li");
    item.textContent = `${index + 1}. ${row.nickname} · ${formatScore(row.finalScore)} · просек ${formatScore(row.playedDays ? row.totalScore / row.playedDays : 0)} · дани ${row.playedDays} · низ ${row.streak}`;
    listingListEl.append(item);
  });
}

function renderPlayerStats(rows) {
  if (!playerStatsEl) return;
  if (!Array.isArray(rows) || !rows.length) {
    playerStatsEl.textContent = "Још нема online статистике за овај надимак.";
    return;
  }

  const stats = aggregatePlayerRows(rows);
  playerStatsEl.textContent = `Коначно ${formatScore(stats.finalScore)} · Победе ${formatScore(stats.wins)} · Покушаји ${formatScore(stats.attempts)} · Најбољи ${formatScore(stats.best)} · Низ ${formatScore(stats.streak)}`;
}

function onlineRowDate(row) {
  const date = new Date(row?.created_at || "");
  if (Number.isNaN(date.getTime())) return "";
  return date.toISOString().slice(0, 10);
}

function restoredResultFromOnline(row) {
  const finalScore = Number(row.score) || 0;
  const started = Math.max(0, Number(row.attempts) || 0);
  const scoreTotal = finalScore + started;
  return {
    status: Number(row.wins) > 0 ? "finished" : "failed",
    date: onlineRowDate(row),
    score: scoreTotal,
    finalScore,
    started,
    completed: Number(row.wins) > 0 ? 4 : 0,
    level: Number(row.wins) > 0 ? 4 : 1,
    words: "",
    points: "враћено из online скора",
    attempts: started,
    wins: Number(row.wins) || 0,
    streak: Number(row.streak) || 0,
    restored: true
  };
}

function restoreLocalResultsFromOnline(rows, nickname = loadPlayerName()) {
  if (!nickname || !Array.isArray(rows)) return false;
  const year = currentYearId();
  const byDate = new Map();
  const localResults = loadResults();
  localResults
    .filter((result) => result?.date && result.date.startsWith(year))
    .forEach((result) => byDate.set(result.date, result));
  rows
    .filter((row) => sameChallengeName(row.nickname, nickname))
    .map(restoredResultFromOnline)
    .filter((result) => result.date && result.date.startsWith(year))
    .forEach((result) => {
      const old = byDate.get(result.date);
      if (!old || Number(result.finalScore) > Number(old.finalScore)) byDate.set(result.date, result);
    });
  const mergedCurrentYear = [...byDate.values()].sort((a, b) => b.date.localeCompare(a.date));
  const merged = [
    ...localResults.filter((result) => !result?.date || !result.date.startsWith(year)),
    ...mergedCurrentYear
  ].sort((a, b) => String(b.date || "").localeCompare(String(a.date || "")));
  if (!merged.length) return false;
  const before = JSON.stringify(localResults);
  const after = JSON.stringify(merged);
  if (before === after) return false;
  saveResults(merged);
  updateScoreDisplay();
  renderListing();
  return true;
}

async function recoverExistingPlayerProfile(name) {
  const rows = await fetchOnlineLeaderboard().catch(() => []);
  if (!Array.isArray(rows) || !rows.some((row) => sameChallengeName(row.nickname, name))) return false;
  savePlayerName(name);
  updateChallengePlayerName();
  const restored = restoreLocalResultsFromOnline(rows, name);
  await hydrateGameSessionsFromCloud({ force: true }).catch(() => false);
  renderProfileModal();
  setProfileEditMode(false);
  setProfileMessage(restored ? "Профил, скор и отворене игре су враћени из online базе." : "Профил је повезан са online надимком.");
  refreshOnlineLeaderboard();
  return true;
}

async function fetchPlayerByDeviceId(targetDeviceId) {
  if (!supabaseConfigured() || !targetDeviceId) return null;
  const query = [
    "select=nickname,device_id,avatar_id",
    `device_id=eq.${encodeURIComponent(targetDeviceId)}`,
    "limit=1"
  ].join("&");
  const response = await fetch(supabaseUrl(`${playersTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return null;
  const rows = await response.json();
  if (Array.isArray(rows)) rows.forEach(cachePlayerAvatar);
  return Array.isArray(rows) && rows.length ? rows[0] : null;
}

async function fetchCurrentPlayerProfile() {
  if (!supabaseConfigured()) return null;
  const name = normalizePlayerName(loadPlayerName() || "");
  const queries = [
    [
      "select=nickname,device_id,avatar_id",
      `device_id=eq.${encodeURIComponent(profileDeviceId())}`,
      "limit=1"
    ].join("&")
  ];
  if (name) {
    queries.push([
      "select=nickname,device_id,avatar_id",
      `nickname=eq.${encodeURIComponent(name)}`,
      "limit=1"
    ].join("&"));
  }
  for (const query of queries) {
    const response = await fetch(supabaseUrl(`${playersTable()}?${query}`), {
      headers: supabaseHeaders()
    });
    if (!response.ok) continue;
    const rows = await response.json();
    if (Array.isArray(rows) && rows.length) {
      rows.forEach(cachePlayerAvatar);
      applySupabaseProfileAvatar(rows[0], name || rows[0].nickname);
      return rows[0];
    }
  }
  return null;
}

async function connectProfileByCode() {
  const targetDeviceId = parseProfileConnectionCode(profileConnectInput?.value || "");
  if (!targetDeviceId) {
    setProfileMessage("Унеси код за повезивање.");
    return;
  }
  if (targetDeviceId === profileDeviceId().toLowerCase()) {
    setProfileMessage("Ово је већ код овог профила.");
    return;
  }
  const row = await fetchPlayerByDeviceId(targetDeviceId);
  const nickname = normalizePlayerName(row?.nickname || "");
  if (!nickname) {
    setProfileMessage("Код није пронађен. Провери да ли је добро копиран.");
    return;
  }
  // Keep this device's identifier for local counters and notifications, but
  // retain the linked profile identity for avatars and challenges.
  localStorage.setItem(PROFILE_DEVICE_ID_KEY, targetDeviceId);
  if (profileAvatarById(row.avatar_id)) {
    applySupabaseProfileAvatar(row, nickname);
  }
  savePlayerName(nickname);
  updateChallengePlayerName();
  // Read this profile's full result history directly. The public leaderboard
  // is capped and can omit an older result when many players are active.
  const onlineRows = await fetchOnlinePlayerStats(nickname).catch(() => []);
  const restored = restoreLocalResultsFromOnline(onlineRows, nickname);
  await hydrateGameSessionsFromCloud({ force: true }).catch(() => false);
  renderProfileModal();
  setProfileEditMode(false);
  if (profileConnectInput) profileConnectInput.value = "";
  setProfileMessage(restored ? "Профил, скор и отворене игре су повезани." : "Профил је повезан. Отворене игре ће се синхронизовати.");
  refreshChallengePanel();
  refreshOnlineLeaderboard();
}

function refreshOnlineLeaderboard() {
  if (!supabaseConfigured() || !listingListEl) return;
  const nickname = loadPlayerName();
  Promise.all([
    fetchOnlineLeaderboard(),
    fetchOnlinePlayerStats(nickname),
    fetchCurrentPlayerProfile().catch(() => null)
  ])
    .then(([rows, stats]) => {
      if (Array.isArray(rows)) {
        restoreLocalResultsFromOnline(stats, nickname);
        renderOnlineLeaderboard(rows);
      }
      if (nickname) renderPlayerStats(stats);
    })
    .catch(() => {
      listingMetaEl.textContent = "локално";
    });
}

